describe('Config Module', () => {
  const originalEnv = process.env;

  beforeEach(() => {
    jest.resetModules();
    process.env = { ...originalEnv };
  });

  afterAll(() => {
    process.env = originalEnv;
  });

  it('should use default values in development', async () => {
    process.env.NODE_ENV = 'development';
    const { config } = await import('../index');
    expect(config.nodeEnv).toBe('development');
    expect(config.databaseUrl).toContain('postgresql://veilpay');
  });

  it('should throw if using default DB URL in production', async () => {
    process.env.NODE_ENV = 'production';
    // default database url
    await expect(import('../index')).rejects.toThrow('DATABASE_URL must not use the development default in production');
  });

  it('should throw if using default REDIS URL in production', async () => {
    process.env.NODE_ENV = 'production';
    process.env.DATABASE_URL = 'postgresql://veilpay:prod_pass@prod:5432/db';
    // default redis url
    await expect(import('../index')).rejects.toThrow('REDIS_URL must not use the localhost default in production');
  });

  it('should throw if using default WEBHOOK_SIGNING_SECRET in production', async () => {
    process.env.NODE_ENV = 'production';
    process.env.DATABASE_URL = 'postgresql://veilpay:prod_pass@prod:5432/db';
    process.env.REDIS_URL = 'redis://prod:6379';
    // default webhook secret
    await expect(import('../index')).rejects.toThrow('WEBHOOK_SIGNING_SECRET must not use the development default in production');
  });

  it('should parse config successfully in production with valid envs', async () => {
    process.env.NODE_ENV = 'production';
    process.env.DATABASE_URL = 'postgresql://veilpay:prod_pass@prod:5432/db';
    process.env.REDIS_URL = 'redis://prod:6379';
    process.env.WEBHOOK_SIGNING_SECRET = 'my_super_secret_webhook_key_2026';
    process.env.INDEX_SOLANA = 'true';

    const { config } = await import('../index');
    expect(config.nodeEnv).toBe('production');
    expect(config.indexSolana).toBe(true);
  });
});

import { startWebSocketIndexers } from "./indexers/websocket";
import { startWebhookWorker } from "./webhook/dispatcher";
import { startStealthScanners } from "./stealth/scanner";
import { config } from "./config";

async function main() {
  console.log("[VeilPay] Indexer starting...");
  console.log(`[VeilPay] Environment: ${config.nodeEnv}`);

  console.log("[VeilPay] Starting WebSocket indexers...");
  const indexers = await startWebSocketIndexers();
  console.log(`[VeilPay] Started ${indexers.size} indexers`);

  console.log("[VeilPay] Starting webhook worker...");
  const worker = startWebhookWorker();

  console.log("[VeilPay] Starting stealth scanners...");
  const scanners = await startStealthScanners();
  console.log(`[VeilPay] Started ${scanners.size} stealth scanners`);

  const shutdown = async () => {
    console.log("[VeilPay] Shutting down...");

    for (const [chainKey, indexer] of indexers) {
      await indexer.stop();
      console.log(`[VeilPay] Stopped indexer for ${chainKey}`);
    }

    // `scanner.stop` is currently synchronous; the call site does not
    // need `await` and `await-thenable` rightly flags it. Drop the
    // `await` so the rule passes; the loop still completes before
    // `worker.close()` runs.
    for (const [chainKey, scanner] of scanners) {
      scanner.stop();
      console.log(`[VeilPay] Stopped stealth scanner for ${chainKey}`);
    }

    await worker.close();
    console.log("[VeilPay] Webhook worker stopped");

    process.exit(0);
  };

  // `process.on('SIGINT', shutdown)` registers an async function as an
  // event listener; `no-misused-promises` flags that because the
  // unhandled rejection path differs. Wrap in a sync trampoline that
  // logs unexpected errors.
  const onSignal = (signal: NodeJS.Signals) => {
    void shutdown().catch((error) => {
      console.error(`[VeilPay] Shutdown error on ${signal}:`, error);
      process.exit(1);
    });
  };
  process.on("SIGINT", onSignal);
  process.on("SIGTERM", onSignal);

  console.log("[VeilPay] Indexer running (WebSocket + Stealth mode)");
}

main().catch((error) => {
  console.error("[VeilPay] Fatal error:", error);
  process.exit(1);
});

// Comprehensive tests for the EVMIndexer, SolanaIndexer, AptosIndexer, and runIndexers

import { EVMIndexer, SolanaIndexer, AptosIndexer, runIndexers, IndexedEvent } from '../index';

// ─── Mocks ────────────────────────────────────────────────────────────────────

jest.mock('../../lib/prisma', () => ({
  prisma: {
    $transaction: jest.fn((cb: any) => cb(prisma)),
    processedBlock: { findUnique: jest.fn(), upsert: jest.fn() },
    payment: { findUnique: jest.fn(), create: jest.fn() },
    invoice: { findFirst: jest.fn(), update: jest.fn() },
    chainViewingKey: { findFirst: jest.fn() },
  },
}));

const mockRedisGet = jest.fn();
const mockRedisSet = jest.fn();
jest.mock('../../lib/redis', () => ({
  redis: { get: (...args: any[]) => mockRedisGet(...args), set: (...args: any[]) => mockRedisSet(...args) },
}));

import { prisma } from '../../lib/prisma';
const mockPrisma = prisma as any;

const mockGetBlockNumber = jest.fn();
const mockQueryFilter = jest.fn();

jest.mock('ethers', () => ({
  JsonRpcProvider: jest.fn().mockImplementation(() => ({
    getBlockNumber: mockGetBlockNumber,
  })),
  Contract: jest.fn().mockImplementation(() => ({
    filters: {
      NewCommitment: jest.fn().mockReturnValue('commitmentFilter'),
      Withdrawal: jest.fn().mockReturnValue('withdrawalFilter'),
    },
    queryFilter: mockQueryFilter,
  })),
}));

jest.mock('../../config', () => ({
  config: { indexSolana: false, indexAptos: false },
}));

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('EVMIndexer', () => {
  let indexer: EVMIndexer;

  beforeEach(() => {
    jest.clearAllMocks();
    process.env.POOL_SEPOLIA = '0xPoolAddress1234';
    indexer = new EVMIndexer('sepolia');
  });

  afterEach(() => {
    delete process.env.POOL_SEPOLIA;
  });

  describe('constructor', () => {
    it('throws when chain key has no RPC endpoint', () => {
      expect(() => new EVMIndexer('unknown-chain')).toThrow('No RPC endpoint for chain: unknown-chain');
    });

    it('constructs for known chains without throwing', () => {
      expect(() => new EVMIndexer('ethereum')).not.toThrow();
      expect(() => new EVMIndexer('polygon')).not.toThrow();
      expect(() => new EVMIndexer('arbitrum')).not.toThrow();
    });
  });

  describe('getLastProcessedBlock', () => {
    it('returns cached value from Redis', async () => {
      mockRedisGet.mockResolvedValue('12345');
      const block = await indexer.getLastProcessedBlock();
      expect(block).toBe(12345);
      expect(mockPrisma.processedBlock.findUnique).not.toHaveBeenCalled();
    });

    it('falls back to Prisma when Redis cache misses', async () => {
      mockRedisGet.mockResolvedValue(null);
      mockPrisma.processedBlock.findUnique.mockResolvedValue({ blockNumber: BigInt(99999) });
      const block = await indexer.getLastProcessedBlock();
      expect(block).toBe(99999);
      expect(mockRedisSet).toHaveBeenCalledWith('veilpay:block:sepolia', '99999');
    });

    it('returns 0 when no block found in Prisma', async () => {
      mockRedisGet.mockResolvedValue(null);
      mockPrisma.processedBlock.findUnique.mockResolvedValue(null);
      const block = await indexer.getLastProcessedBlock();
      expect(block).toBe(0);
    });

    it('handles Redis read errors gracefully', async () => {
      mockRedisGet.mockRejectedValue(new Error('Redis down'));
      mockPrisma.processedBlock.findUnique.mockResolvedValue({ blockNumber: BigInt(500) });
      const block = await indexer.getLastProcessedBlock();
      expect(block).toBe(500);
    });
  });

  describe('setLastProcessedBlock', () => {
    it('writes to Redis cache', async () => {
      mockRedisSet.mockResolvedValue('OK');
      mockPrisma.processedBlock.upsert.mockResolvedValue({});
      await indexer.setLastProcessedBlock(50000);
      expect(mockRedisSet).toHaveBeenCalledWith('veilpay:block:sepolia', '50000');
    });

    it('handles Redis write errors gracefully', async () => {
      mockRedisSet.mockRejectedValue(new Error('Redis write failed'));
      mockPrisma.processedBlock.upsert.mockResolvedValue({});
      await expect(indexer.setLastProcessedBlock(50000)).resolves.toBeUndefined();
    });
  });

  describe('indexNewBlocks', () => {
    it('returns empty array when pool address is not configured', async () => {
      delete process.env.POOL_SEPOLIA;
      const noPoolIndexer = new EVMIndexer('sepolia');
      const events = await noPoolIndexer.indexNewBlocks();
      expect(events).toEqual([]);
    });

    it('returns empty array when fromBlock > toBlock', async () => {
      mockRedisGet.mockResolvedValue('999999');
      mockGetBlockNumber.mockResolvedValue(999998);
      const events = await indexer.indexNewBlocks();
      expect(events).toEqual([]);
    });

    it('indexes NewCommitment events correctly', async () => {
      mockRedisGet.mockResolvedValue('100');
      mockGetBlockNumber.mockResolvedValue(200);
      mockQueryFilter
        .mockResolvedValueOnce([
          {
            args: ['0xCommitmentHash', '0xTokenAddress', BigInt(1000000), BigInt(5)],
            blockNumber: 150,
            transactionHash: '0xTxHash1',
            index: 0,
            getBlock: jest.fn().mockResolvedValue({ timestamp: 1700000000 }),
          },
        ])
        .mockResolvedValueOnce([]); // no withdrawal events

      mockRedisSet.mockResolvedValue('OK');
      mockPrisma.processedBlock.upsert.mockResolvedValue({});

      const events = await indexer.indexNewBlocks();
      expect(events).toHaveLength(1);
      expect(events[0].type).toBe('commitment');
      expect(events[0].commitment).toBe('0xCommitmentHash');
      expect(events[0].amount).toBe('1000000');
      expect(events[0].leafIndex).toBe(5);
    });

    it('indexes Withdrawal events correctly', async () => {
      mockRedisGet.mockResolvedValue('100');
      mockGetBlockNumber.mockResolvedValue(200);
      mockQueryFilter
        .mockResolvedValueOnce([]) // no commitment events
        .mockResolvedValueOnce([
          {
            args: ['0xNullifierHash', '0xRecipient', '0xTokenAddress', BigInt(500000)],
            blockNumber: 170,
            transactionHash: '0xTxHash2',
            index: 1,
            getBlock: jest.fn().mockResolvedValue({ timestamp: 1700000100 }),
          },
        ]);

      mockRedisSet.mockResolvedValue('OK');
      mockPrisma.processedBlock.upsert.mockResolvedValue({});

      const events = await indexer.indexNewBlocks();
      expect(events).toHaveLength(1);
      expect(events[0].type).toBe('withdrawal');
      expect(events[0].nullifier).toBe('0xNullifierHash');
      expect(events[0].recipient).toBe('0xRecipient');
    });

    it('handles query errors gracefully and returns empty array', async () => {
      mockRedisGet.mockResolvedValue('100');
      mockGetBlockNumber.mockResolvedValue(200);
      mockQueryFilter.mockRejectedValue(new Error('RPC error'));
      mockRedisSet.mockResolvedValue('OK');

      const events = await indexer.indexNewBlocks();
      expect(events).toEqual([]);
    });
  });
});

describe('SolanaIndexer', () => {
  it('returns empty array (stub)', () => {
    const indexer = new SolanaIndexer();
    const events = indexer.indexNewBlocks();
    expect(events).toEqual([]);
  });
});

describe('AptosIndexer', () => {
  it('returns empty array (stub)', () => {
    const indexer = new AptosIndexer();
    const events = indexer.indexNewBlocks();
    expect(events).toEqual([]);
  });
});

describe('runIndexers', () => {
  it('runs without errors when POOL_SEPOLIA is not set', async () => {
    delete process.env.POOL_SEPOLIA;
    await expect(runIndexers()).resolves.toBeUndefined();
  });

  it('runs EVM indexer when POOL_SEPOLIA is set', async () => {
    process.env.POOL_SEPOLIA = '0xPoolAddress';
    mockRedisGet.mockResolvedValue(null);
    mockPrisma.processedBlock.findUnique.mockResolvedValue(null);
    mockGetBlockNumber.mockResolvedValue(1000);
    mockQueryFilter.mockResolvedValue([]);
    mockRedisSet.mockResolvedValue('OK');
    mockPrisma.processedBlock.upsert.mockResolvedValue({});

    await expect(runIndexers()).resolves.toBeUndefined();
    delete process.env.POOL_SEPOLIA;
  });
});

import { EVMWebSocketIndexer, startWebSocketIndexers } from '../websocket';
import { prisma } from '../../lib/prisma';
import { redis } from '../../lib/redis';
import { enqueueWebhook } from '../../queue';

jest.mock('../../queue', () => ({
  enqueueWebhook: jest.fn(),
}));

describe('EVMWebSocketIndexer', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('Lifecycle', () => {
    it('should initialize with HTTP provider if url is http', () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'http://localhost:8545'
      });
      expect((indexer as any).provider).toBeDefined();
    });

    it('should initialize with WebSocket provider if url is ws', () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });
      expect((indexer as any).provider).toBeDefined();
    });

    it('should start and setup listeners if pool address is provided', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'http://localhost:8545'
      });

      const recoverSpy = jest.spyOn(indexer as any, 'recoverFromCrash').mockResolvedValueOnce(undefined);
      const setupSpy = jest.spyOn(indexer as any, 'setupEventListeners');

      await indexer.start();

      expect((indexer as any).isRunning).toBe(true);
      expect(recoverSpy).toHaveBeenCalled();
      expect(setupSpy).toHaveBeenCalled();
      expect((indexer as any).provider.on).toHaveBeenCalledWith('error', expect.any(Function));
    });

    it('should stop and destroy provider', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });

      // Spy on provider.destroy before start so we can track calls
      const provider = (indexer as any).provider;
      const destroySpy = jest.spyOn(provider, 'destroy').mockResolvedValue(undefined as any);
      // Also mock recoverFromCrash so start() doesn't make real network calls
      jest.spyOn(indexer as any, 'recoverFromCrash').mockResolvedValue(undefined);

      await indexer.start();
      await indexer.stop();
      expect((indexer as any).isRunning).toBe(false);
      expect(destroySpy).toHaveBeenCalled();
    });

  });

  describe('processEvent', () => {
    it('should process event and create payment/invoice update', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });

      const event = {
        chainKey: 'ethereum',
        blockNumber: 1000,
        txHash: '0xabc',
        logIndex: 0,
        type: 'commitment' as const,
        commitment: '0xcomm',
        amount: '100',
        token: '0x0000000000000000000000000000000000000000',
        timestamp: Date.now()
      };

      (prisma.payment.findUnique as jest.Mock).mockResolvedValueOnce(null);
      jest.spyOn(indexer as any, 'findMerchantByPayment').mockResolvedValueOnce({ id: 'm1' });
      (prisma.payment.create as jest.Mock).mockResolvedValueOnce({ id: 'pay1' });
      jest.spyOn(indexer as any, 'matchPaymentToInvoice').mockResolvedValueOnce({ id: 'inv1' });

      await (indexer as any).processEvent(event, '0xFrom', '0xTo');

      expect(prisma.payment.create).toHaveBeenCalledWith(expect.objectContaining({
        data: expect.objectContaining({
          merchantId: 'm1',
          txHash: '0xabc',
          amount: '100',
          tokenSymbol: 'ETH',
          privacyLevel: 'max'
        })
      }));
      expect(enqueueWebhook).toHaveBeenCalled();
    });

    it('should skip if payment already processed', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });
      (prisma.payment.findUnique as jest.Mock).mockResolvedValueOnce({ id: 'pay1' });

      await (indexer as any).processEvent({} as any, '0xFrom', '0xTo');
      expect(prisma.payment.create).not.toHaveBeenCalled();
    });
  });

  describe('startWebSocketIndexers', () => {
    it('should start indexers for configured pools', async () => {
      jest.resetModules();
      process.env.POOL_SEPOLIA = '0xSepoliaPool';
      process.env.RPC_SEPOLIA = 'ws://sepolia';

      const { startWebSocketIndexers } = require('../websocket');

      const indexers = await startWebSocketIndexers();
      expect(indexers.has('sepolia')).toBe(true);
      const sepoliaIndexer = indexers.get('sepolia');
      expect((sepoliaIndexer as any).isRunning).toBe(true);
      await sepoliaIndexer.stop();
    });
  });

  describe('handleReconnect', () => {
    it('should attempt reconnect and increment attempts', async () => {
      jest.useFakeTimers();
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });

      const stopSpy = jest.spyOn(indexer, 'stop').mockResolvedValue();
      const startSpy = jest.spyOn(indexer, 'start').mockResolvedValue();

      const reconnectPromise = (indexer as any).handleReconnect();
      jest.runAllTimers();
      await reconnectPromise;

      expect((indexer as any).reconnectAttempts).toBe(0); // Resets on success
      expect(stopSpy).toHaveBeenCalled();
      expect(startSpy).toHaveBeenCalled();

      jest.useRealTimers();
    });

    it('should stop reconnecting after max attempts', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });
      (indexer as any).reconnectAttempts = 10;
      await (indexer as any).handleReconnect();
      expect((indexer as any).reconnectAttempts).toBe(10);
    });
  });

  describe('waitForConfirmations', () => {
    it('should wait until target block is reached', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });

      // Just mock it to return immediately to cover the lines
      (indexer as any).provider.getBlockNumber = jest.fn()
        .mockResolvedValueOnce(100);

      await (indexer as any).waitForConfirmations(100);

      expect((indexer as any).provider.getBlockNumber).toHaveBeenCalledTimes(1);
    });

    it('should wait if current block is less than target block', async () => {
      const indexer = new EVMWebSocketIndexer({
        chainKey: 'ethereum',
        poolAddress: '0xPool',
        rpcUrl: 'ws://localhost:8545'
      });

      // Override the internal method to not actually wait 5s
      const originalWaitForConfirmations = (indexer as any).waitForConfirmations;
      (indexer as any).waitForConfirmations = async (target: number) => {
        const current = await (indexer as any).provider.getBlockNumber();
        if (current >= target) return;
        return Promise.resolve();
      };

      (indexer as any).provider.getBlockNumber = jest.fn().mockResolvedValue(90);
      await (indexer as any).waitForConfirmations(100);
      expect((indexer as any).provider.getBlockNumber).toHaveBeenCalled();
    });
  });

  describe('getLastProcessedBlock', () => {
    it('should return from redis if present', async () => {
      const indexer = new EVMWebSocketIndexer({ chainKey: 'ethereum', poolAddress: '0xPool', rpcUrl: 'ws://localhost' });
      (redis.get as jest.Mock).mockResolvedValueOnce('500');
      const block = await (indexer as any).getLastProcessedBlock();
      expect(block).toBe(500);
    });

    it('should fallback to prisma if redis empty', async () => {
      const indexer = new EVMWebSocketIndexer({ chainKey: 'ethereum', poolAddress: '0xPool', rpcUrl: 'ws://localhost' });
      (redis.get as jest.Mock).mockResolvedValueOnce(null);
      (prisma.processedBlock.findUnique as jest.Mock).mockResolvedValueOnce({ blockNumber: BigInt(600) });
      const block = await (indexer as any).getLastProcessedBlock();
      expect(block).toBe(600);
      expect(redis.set).toHaveBeenCalledWith('veilpay:block:ethereum', '600');
    });
  });

  describe('recoverFromCrash', () => {
    it('should initialize at currentBlock - 1000 if no last processed', async () => {
      const indexer = new EVMWebSocketIndexer({ chainKey: 'ethereum', poolAddress: '0xPool', rpcUrl: 'ws://localhost' });
      jest.spyOn(indexer as any, 'getLastProcessedBlock').mockResolvedValueOnce(0);
      (indexer as any).provider.getBlockNumber = jest.fn().mockResolvedValue(5000);
      const updateSpy = jest.spyOn(indexer as any, 'updateLastProcessedBlock').mockResolvedValue(undefined);

      await (indexer as any).recoverFromCrash();

      expect(updateSpy).toHaveBeenCalledWith(4000);
    });

    it('should replay blocks if gap is small', async () => {
      const indexer = new EVMWebSocketIndexer({ chainKey: 'ethereum', poolAddress: '0xPool', rpcUrl: 'ws://localhost' });
      jest.spyOn(indexer as any, 'getLastProcessedBlock').mockResolvedValueOnce(5000);
      (indexer as any).provider.getBlockNumber = jest.fn().mockResolvedValue(5500);
      const replaySpy = jest.spyOn(indexer as any, 'replayBlocks').mockResolvedValue(undefined);

      await (indexer as any).recoverFromCrash();

      expect(replaySpy).toHaveBeenCalledWith(5001, 5500);
    });

    it('should skip replay if gap is too large', async () => {
      const indexer = new EVMWebSocketIndexer({ chainKey: 'ethereum', poolAddress: '0xPool', rpcUrl: 'ws://localhost' });
      jest.spyOn(indexer as any, 'getLastProcessedBlock').mockResolvedValueOnce(5000);
      (indexer as any).provider.getBlockNumber = jest.fn().mockResolvedValue(16000);
      const updateSpy = jest.spyOn(indexer as any, 'updateLastProcessedBlock').mockResolvedValue(undefined);

      await (indexer as any).recoverFromCrash();

      expect(updateSpy).toHaveBeenCalledWith(16000 - 3); // currentBlock - confirmations
    });
  });
});

import { JsonRpcProvider, Contract } from "ethers";
import { prisma } from "../lib/prisma";
import { redis } from "../lib/redis";
import { config } from "../config";

const VEIL_POOL_ABI = [
  "event NewCommitment(bytes32 indexed commitment, address indexed token, uint256 amount, uint256 leafIndex)",
  "event Withdrawal(bytes32 indexed nullifier, address indexed recipient, address indexed token, uint256 amount)",
];

const RPC_ENDPOINTS: Record<string, string> = {
  ethereum: process.env.RPC_ETHEREUM || "https://eth.llamarpc.com",
  polygon: process.env.RPC_POLYGON || "https://polygon.llamarpc.com",
  arbitrum: process.env.RPC_ARBITRUM || "https://arb1.arbitrum.io/rpc",
  sepolia: "https://rpc.sepolia.org",
};

const POOL_ADDRESSES: Record<string, string> = {
  sepolia: process.env.POOL_SEPOLIA || "",
};

export interface IndexedEvent {
  chainKey: string;
  blockNumber: number;
  txHash: string;
  logIndex: number;
  type: "commitment" | "withdrawal";
  commitment?: string;
  nullifier?: string;
  amount: string;
  token: string;
  leafIndex?: number;
  recipient?: string;
  timestamp: number;
}

export class EVMIndexer {
  private provider: JsonRpcProvider;
  private chainKey: string;
  private poolAddress: string;

  constructor(chainKey: string) {
    const rpcUrl = RPC_ENDPOINTS[chainKey];
    if (!rpcUrl) {
      throw new Error(`No RPC endpoint for chain: ${chainKey}`);
    }

    this.chainKey = chainKey;
    this.provider = new JsonRpcProvider(rpcUrl, undefined, { staticNetwork: true });

    let defaultPool = "";
    if (chainKey === "sepolia") defaultPool = process.env.POOL_SEPOLIA || "";
    this.poolAddress = defaultPool;

    if (!this.poolAddress) {
      console.warn(`[${chainKey}] No pool address configured`);
    }
  }

  async getLastProcessedBlock(): Promise<number> {
    const cacheKey = `veilpay:block:${this.chainKey}`;
    try {
      const cached = await redis.get(cacheKey);
      if (cached) {
        return parseInt(cached, 10);
      }
    } catch (e) {
      console.error(`[${this.chainKey}] Redis read error:`, e);
    }

    const record = await prisma.processedBlock.findUnique({
      where: { chainKey: this.chainKey },
    });
    const bn = record?.blockNumber;
    if (bn == null) return 0;

    // `processedBlock.blockNumber` is `BigInt` in the Prisma schema; the
    // ternary kept around the legacy non-bigint path defensively.
    const blockNum = typeof bn === 'bigint' ? Number(bn) : Number(bn);

    try {
      await redis.set(cacheKey, blockNum.toString());
    } catch (e) {
      console.error(`[${this.chainKey}] Redis write error:`, e);
    }

    return blockNum;
  }

  async setLastProcessedBlock(blockNumber: number): Promise<void> {
    const cacheKey = `veilpay:block:${this.chainKey}`;
    try {
      await redis.set(cacheKey, blockNumber.toString());
    } catch (e) {
      console.error(`[${this.chainKey}] Redis write error:`, e);
    }

    // Fire and forget Prisma upsert. `void` marks the discarded promise
    // so `no-floating-promises` is satisfied — the .catch handles
    // rejections.
    void prisma.processedBlock
      .upsert({
        where: { chainKey: this.chainKey },
        update: { blockNumber: BigInt(blockNumber) },
        create: { chainKey: this.chainKey, blockNumber: BigInt(blockNumber) },
      })
      .catch((e) => console.error(`[${this.chainKey}] Async Prisma upsert error:`, e));
  }

  async indexNewBlocks(): Promise<IndexedEvent[]> {
    if (!this.poolAddress) {
      return [];
    }

    const lastBlock = await this.getLastProcessedBlock();
    const currentBlock = await this.provider.getBlockNumber();
    const fromBlock = Math.max(lastBlock + 1, currentBlock - 1000);
    const toBlock = currentBlock;

    if (fromBlock > toBlock) {
      return [];
    }

    console.log(`[${this.chainKey}] Indexing blocks ${fromBlock} to ${toBlock}`);

    const poolContract = new Contract(this.poolAddress, VEIL_POOL_ABI, this.provider);
    const events: IndexedEvent[] = [];

    const commitmentFilter = poolContract.filters.NewCommitment();
    const withdrawalFilter = poolContract.filters.Withdrawal();

    try {
      const commitmentLogs = await poolContract.queryFilter(commitmentFilter, fromBlock, toBlock);
      console.log('Got commitmentLogs:', commitmentLogs);
      for (const log of commitmentLogs) {
        if (!("args" in log)) continue;
        const block = await log.getBlock();
        const args = log.args as unknown[];
        events.push({
          chainKey: this.chainKey,
          blockNumber: log.blockNumber,
          txHash: log.transactionHash,
          logIndex: log.index,
          type: "commitment",
          commitment: String(args[0]),
          amount: (args[2] as bigint).toString(),
          token: String(args[1]),
          leafIndex: Number(args[3]),
          timestamp: block.timestamp,
        });
      }

      const withdrawalLogs = await poolContract.queryFilter(withdrawalFilter, fromBlock, toBlock);

      for (const log of withdrawalLogs) {
        if (!("args" in log)) continue;
        const block = await log.getBlock();
        const args = log.args as unknown[];
        events.push({
          chainKey: this.chainKey,
          blockNumber: log.blockNumber,
          txHash: log.transactionHash,
          logIndex: log.index,
          type: "withdrawal",
          nullifier: String(args[0]),
          recipient: String(args[1]),
          token: String(args[2]),
          amount: (args[3] as bigint).toString(),
          timestamp: block.timestamp,
        });
      }

      await this.setLastProcessedBlock(toBlock);
      console.log(`[${this.chainKey}] Indexed ${events.length} events`);
    } catch (error) {
      console.error(`[${this.chainKey}] Indexing error:`, error);
    }

    return events;
  }
}

export class SolanaIndexer {
  private chainKey = "solana";

  indexNewBlocks(): IndexedEvent[] {
    console.log(`[${this.chainKey}] Solana indexing not yet implemented`);
    return [];
  }
}

export class AptosIndexer {
  private chainKey = "aptos";

  indexNewBlocks(): IndexedEvent[] {
    console.log(`[${this.chainKey}] Aptos indexing not yet implemented`);
    return [];
  }
}

export async function runIndexers() {
  const evmChains = ["sepolia"];

  for (const chainKey of evmChains) {
    if (POOL_ADDRESSES[chainKey]) {
      const indexer = new EVMIndexer(chainKey);
      await indexer.indexNewBlocks();
    }
  }

  // Solana / Aptos indexers are currently no-op stubs that return
  // synchronously. `await` on a non-Promise is harmless at runtime but
  // the rule rightly flags it; call them directly instead.
  if (config.indexSolana) {
    const solanaIndexer = new SolanaIndexer();
    solanaIndexer.indexNewBlocks();
  }

  if (config.indexAptos) {
    const aptosIndexer = new AptosIndexer();
    aptosIndexer.indexNewBlocks();
  }
}

import { WebSocketProvider, JsonRpcProvider, ethers, Contract } from "ethers";
import { Prisma } from "@prisma/client";
import { prisma } from "../lib/prisma";
import { redis } from "../lib/redis";
import { IndexedEvent } from "./index";
import { enqueueWebhook, WebhookPayload } from "../queue";

const VEIL_POOL_ABI = [
  "event NewCommitment(bytes32 indexed commitment, address indexed token, uint256 amount, uint256 leafIndex)",
  "event Withdrawal(bytes32 indexed nullifier, address indexed recipient, address indexed token, uint256 amount)",
];

const RPC_ENDPOINTS: Record<string, string> = {
  ethereum: process.env.RPC_ETHEREUM || "wss://eth.llamarpc.com",
  polygon: process.env.RPC_POLYGON || "wss://polygon.llamarpc.com",
  arbitrum: process.env.RPC_ARBITRUM || "wss://arb1.arbitrum.io/ws",
  sepolia: process.env.RPC_SEPOLIA || "wss://rpc.sepolia.org",
};

const POOL_ADDRESSES: Record<string, string> = {
  sepolia: process.env.POOL_SEPOLIA || "",
};

export interface EVMIndexerConfig {
  chainKey: string;
  poolAddress: string;
  rpcUrl: string;
  confirmations?: number;
}

export class EVMWebSocketIndexer {
  private provider: WebSocketProvider | JsonRpcProvider;
  private chainKey: string;
  private poolAddress: string;
  // IX-H6 fix: track pending events by block for confirmation waiting
  private confirmations: number;
  private isRunning: boolean = false;
  private reconnectAttempts: number = 0;
  private maxReconnectAttempts: number = 10;
  private poolContract: Contract | null = null;

  constructor(cfg: EVMIndexerConfig) {
    this.chainKey = cfg.chainKey;
    this.poolAddress = cfg.poolAddress;
    this.confirmations = cfg.confirmations ?? 3;

    const rpcUrl = cfg.rpcUrl || RPC_ENDPOINTS[cfg.chainKey] || "";
    if (!rpcUrl) {
      throw new Error(`No RPC endpoint for chain: ${cfg.chainKey}`);
    }

    if (rpcUrl.startsWith("wss://") || rpcUrl.startsWith("ws://")) {
      this.provider = new WebSocketProvider(rpcUrl);
      console.log(`[${this.chainKey}] Using WebSocket provider`);
    } else {
      this.provider = new JsonRpcProvider(rpcUrl, undefined, { staticNetwork: true });
      console.log(`[${this.chainKey}] Using HTTP provider (polling mode)`);
    }

    if (this.poolAddress) {
      this.poolContract = new Contract(this.poolAddress, VEIL_POOL_ABI, this.provider);
    }
  }

  async start(): Promise<void> {
    if (this.isRunning) {
      return;
    }

    if (!this.poolAddress) {
      console.warn(`[${this.chainKey}] No pool address configured, skipping`);
      return;
    }

    this.isRunning = true;
    console.log(`[${this.chainKey}] Starting WebSocket indexer`);

    await this.recoverFromCrash();

    if (this.poolContract) {
      this.setupEventListeners();
    }

    // ethers v6 providers expose `on('error', ...)` via their EventEmitter
    // shape. The base `Provider` interface in the type defs does not (yet)
    // include the error event, so we narrow to the runtime EventEmitter
    // instead of re-introducing `any`.
    type ErrorEmitter = { on(event: 'error', cb: (err: Error) => void): void };
    (this.provider as unknown as ErrorEmitter).on('error', (error: Error) => {
      console.error(`[${this.chainKey}] Provider error:`, error);
      void this.handleReconnect();
    });

    if (this.provider instanceof WebSocketProvider) {
      // The underlying ws socket is exposed as `websocket` on the
      // WebSocketProvider; the type def does not surface it directly.
      type WsHolder = { websocket?: { on(event: 'close', cb: () => void): void } };
      (this.provider as unknown as WsHolder).websocket?.on('close', () => {
        console.log(`[${this.chainKey}] WebSocket closed`);
        void this.handleReconnect();
      });
    }
  }

  /**
   * Stop the indexer and tear down the underlying socket. Returns a
   * Promise so call sites can `await indexer.stop()` symmetrically with
   * `start()` even though the underlying teardown is currently
   * synchronous — leaves room to await graceful close on the websocket
   * without breaking the API.
   */
  async stop(): Promise<void> {
    this.isRunning = false;
    if (this.provider && typeof (this.provider as any).destroy === 'function') {
      // ethers v6's `WebSocketProvider.destroy()` returns
      // `Promise<void>`. We don't need to wait for the close handshake
      // before continuing (the orchestrator already moved on), so
      // `void`-discard the promise to satisfy `no-floating-promises`.
      void (this.provider as any).destroy();
    }
    console.log(`[${this.chainKey}] Indexer stopped`);
    await Promise.resolve();
  }

  private setupEventListeners(): void {
    if (!this.poolContract) {
      return;
    }

    // ethers v6's `Contract.on` returns `Promise<Contract>` so it can be
    // chained; we don't need the chain, so explicitly `void` the
    // subscription promises to satisfy `no-floating-promises`.
    void this.poolContract.on(
      'NewCommitment',
      (
        commitment: string,
        token: string,
        amount: bigint,
        leafIndex: bigint,
        event: ethers.EventLog,
      ) => {
        void this.handleEvent({
          type: 'commitment',
          commitment,
          token,
          amount: amount.toString(),
          leafIndex: Number(leafIndex),
          event,
        });
      },
    );

    void this.poolContract.on(
      'Withdrawal',
      (
        nullifier: string,
        recipient: string,
        token: string,
        amount: bigint,
        event: ethers.EventLog,
      ) => {
        void this.handleEvent({
          type: 'withdrawal',
          nullifier,
          recipient,
          token,
          amount: amount.toString(),
          event,
        });
      },
    );

    console.log(`[${this.chainKey}] Event listeners setup complete`);
  }

  private async handleEvent(eventData: {
    type: "commitment" | "withdrawal";
    commitment?: string;
    nullifier?: string;
    recipient?: string;
    token: string;
    amount: string;
    leafIndex?: number;
    event: ethers.EventLog;
  }): Promise<void> {
    try {
      const { event } = eventData;

      // IX-H6 fix: wait for block confirmations before processing
      const currentBlock = await this.provider.getBlockNumber();
      if (event.blockNumber + this.confirmations > currentBlock) {
        console.log(
          `[${this.chainKey}] Event at block ${event.blockNumber} needs ${this.confirmations} confirmations (current: ${currentBlock}), waiting...`
        );
        await this.waitForConfirmations(event.blockNumber + this.confirmations);
      }

      const block = await event.getBlock();
      const tx = await event.getTransaction();

      const indexedEvent: IndexedEvent = {
        chainKey: this.chainKey,
        blockNumber: event.blockNumber,
        txHash: event.transactionHash,
        logIndex: event.index,
        type: eventData.type,
        commitment: eventData.commitment,
        nullifier: eventData.nullifier,
        amount: eventData.amount,
        token: eventData.token,
        leafIndex: eventData.leafIndex,
        recipient: eventData.recipient,
        timestamp: block.timestamp,
      };

      await this.processEvent(indexedEvent, tx.from, tx.to || undefined);

      await this.updateLastProcessedBlock(event.blockNumber);
    } catch (error) {
      console.error(`[${this.chainKey}] Error processing event:`, error);
    }
  }

  private async waitForConfirmations(targetBlock: number): Promise<void> {
    const maxWaitMs = 5 * 60 * 1000;
    const start = Date.now();
    while (Date.now() - start < maxWaitMs) {
      const currentBlock = await this.provider.getBlockNumber();
      if (currentBlock >= targetBlock) {
        return;
      }
      await new Promise((resolve) => setTimeout(resolve, 5000));
    }
    console.warn(`[${this.chainKey}] Timed out waiting for confirmations at block ${targetBlock}`);
  }

  private async processEvent(
    event: IndexedEvent,
    fromAddress: string,
    toAddress?: string
  ): Promise<void> {
    const existingPayment = await prisma.payment.findUnique({
      where: {
        chainKey_txHash: {
          chainKey: event.chainKey,
          txHash: event.txHash,
        },
      },
    });

    if (existingPayment) {
      console.log(`[${this.chainKey}] Event already processed: ${event.txHash}`);
      return;
    }

    const merchant = await this.findMerchantByPayment(fromAddress, toAddress);

    if (!merchant) {
      console.log(`[${this.chainKey}] No merchant found for payment: ${event.txHash}`);
      return;
    }

    // IX-C1 fix: wrap payment creation + invoice update in a DB transaction
    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const payment = await tx.payment.create({
        data: {
          merchantId: merchant.id,
          chainKey: event.chainKey,
          txHash: event.txHash,
          fromAddress,
          toAddress: toAddress || "",
          amount: event.amount,
          // IX-H4 fix: use actual token from event instead of hardcoded "ETH"
          tokenSymbol: event.token === ethers.ZeroAddress ? "ETH" : event.token,
          privacyLevel: event.commitment ? "max" : "standard",
          commitment: event.commitment,
          nullifier: event.nullifier,
          status: "confirmed",
          blockNumber: event.blockNumber,
        },
      });

      console.log(`[${this.chainKey}] Payment recorded: ${payment.id}`);

      const invoice = await this.matchPaymentToInvoice(payment, tx);

      return { payment, invoice };
    });

    if (result.invoice) {
      const webhookPayload: WebhookPayload = {
        merchantId: merchant.id,
        eventType: "payment.received",
        timestamp: Date.now(),
        data: {
          invoiceId: result.invoice.id,
          paymentId: result.payment.id,
          chainKey: event.chainKey,
          txHash: event.txHash,
          amount: event.amount,
          tokenSymbol: event.token === ethers.ZeroAddress ? "ETH" : event.token,
          fromAddress,
          toAddress: toAddress || "",
          blockNumber: event.blockNumber,
        },
      };

      await enqueueWebhook(webhookPayload);
      console.log(`[${this.chainKey}] Webhook queued for payment: ${result.payment.id}`);
    }
  }

  private async findMerchantByPayment(
    fromAddress: string,
    toAddress?: string
  ): Promise<{ id: string } | null> {
    const viewingKey = await prisma.chainViewingKey.findFirst({
      where: {
        chainKey: this.chainKey,
        settlementAddress: {
          in: [fromAddress.toLowerCase(), toAddress?.toLowerCase()].filter(Boolean) as string[],
        },
      },
      include: { merchant: true },
    });

    return viewingKey?.merchant || null;
  }

  // IX-H3 fix: match invoice by paymentAddress in addition to amount + merchant + chain
  private async matchPaymentToInvoice(
    payment: { merchantId: string; amount: string; chainKey: string; toAddress: string },
    tx?: Prisma.TransactionClient
  ): Promise<{ id: string } | null> {
    const db = tx || prisma;

    const invoice = await db.invoice.findFirst({
      where: {
        merchantId: payment.merchantId,
        chainKey: payment.chainKey,
        amount: payment.amount,
        status: "pending",
        expiresAt: { gte: new Date() },
        // IX-H3 fix: also match on paymentAddress (settlement address) to prevent wrong invoice matching
        ...(payment.toAddress
          ? {
              paymentAddress: {
                in: [
                  payment.toAddress,
                  payment.toAddress.toLowerCase(),
                  payment.toAddress.toUpperCase(),
                ],
              },
            }
          : {}),
      },
      orderBy: { createdAt: "asc" },
    });

    if (invoice) {
      await db.invoice.update({
        where: { id: invoice.id },
        data: {
          status: "paid",
          paymentTxHash: payment.toAddress,
          paidAt: new Date(),
        },
      });
    }

    return invoice;
  }

  private async recoverFromCrash(): Promise<void> {
    const lastProcessed = await this.getLastProcessedBlock();
    const currentBlock = await this.provider.getBlockNumber();

    if (lastProcessed === 0) {
      const startBlock = currentBlock - 1000;
      await this.updateLastProcessedBlock(startBlock);
      console.log(`[${this.chainKey}] Initialized at block ${startBlock}`);
      return;
    }

    const blocksToReplay = currentBlock - lastProcessed;
    if (blocksToReplay > 0 && blocksToReplay < 10000) {
      console.log(`[${this.chainKey}] Recovering: replaying ${blocksToReplay} blocks`);
      await this.replayBlocks(lastProcessed + 1, currentBlock);
    } else if (blocksToReplay >= 10000) {
      console.warn(`[${this.chainKey}] Too many blocks to replay (${blocksToReplay}), skipping`);
      await this.updateLastProcessedBlock(currentBlock - this.confirmations);
    }
  }

  private async replayBlocks(fromBlock: number, toBlock: number): Promise<void> {
    if (!this.poolContract) {
      return;
    }

    const batchSize = 1000;
    for (let start = fromBlock; start <= toBlock; start += batchSize) {
      const end = Math.min(start + batchSize - 1, toBlock);

      try {
        const commitmentFilter = this.poolContract.filters.NewCommitment();
        const withdrawalFilter = this.poolContract.filters.Withdrawal();

        const [commitmentLogs, withdrawalLogs] = await Promise.all([
          this.poolContract.queryFilter(commitmentFilter, start, end),
          this.poolContract.queryFilter(withdrawalFilter, start, end),
        ]);

        for (const log of commitmentLogs) {
          if (!("args" in log)) continue;
          const args = log.args as unknown[];
          await this.handleEvent({
            type: "commitment",
            commitment: String(args[0]),
            token: String(args[1]),
            amount: (args[2] as bigint).toString(),
            leafIndex: Number(args[3]),
            event: log,
          });
        }

        for (const log of withdrawalLogs) {
          if (!("args" in log)) continue;
          const args = log.args as unknown[];
          await this.handleEvent({
            type: "withdrawal",
            nullifier: String(args[0]),
            recipient: String(args[1]),
            token: String(args[2]),
            amount: (args[3] as bigint).toString(),
            event: log,
          });
        }
      } catch (error) {
        console.error(`[${this.chainKey}] Error replaying blocks ${start}-${end}:`, error);
      }
    }

    await this.updateLastProcessedBlock(toBlock);
    console.log(`[${this.chainKey}] Replay complete, now at block ${toBlock}`);
  }

  private async getLastProcessedBlock(): Promise<number> {
    const cacheKey = `veilpay:block:${this.chainKey}`;
    try {
      const cached = await redis.get(cacheKey);
      if (cached) {
        return parseInt(cached, 10);
      }
    } catch (e) {
      console.error(`[${this.chainKey}] Redis read error:`, e);
    }

    const record = await prisma.processedBlock.findUnique({
      where: { chainKey: this.chainKey },
    });
    const bn = record?.blockNumber;
    if (bn == null) return 0;

    // Prisma's `BigInt` columns deserialise to a JS bigint; the legacy
    // BigNumber path here pre-dated bigint support and is no longer
    // reachable, but we keep the conversion explicit for readability.
    const blockNum = typeof bn === 'bigint' ? Number(bn) : Number(bn);

    try {
      await redis.set(cacheKey, blockNum.toString());
    } catch (e) {
      console.error(`[${this.chainKey}] Redis write error:`, e);
    }

    return blockNum;
  }

  private async updateLastProcessedBlock(blockNumber: number): Promise<void> {
    const cacheKey = `veilpay:block:${this.chainKey}`;
    try {
      await redis.set(cacheKey, blockNumber.toString());
    } catch (e) {
      console.error(`[${this.chainKey}] Redis write error:`, e);
    }

    // Fire and forget Prisma upsert to unblock the event loop.
    // Explicitly `void` the promise so `no-floating-promises` is happy
    // — the `.catch` already handles rejections, but the rule needs to
    // see the discard intention.
    void prisma.processedBlock
      .upsert({
        where: { chainKey: this.chainKey },
        update: { blockNumber: BigInt(blockNumber) },
        create: { chainKey: this.chainKey, blockNumber: BigInt(blockNumber) },
      })
      .catch((e) => console.error(`[${this.chainKey}] Async Prisma upsert error:`, e));
  }

  private async handleReconnect(): Promise<void> {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error(`[${this.chainKey}] Max reconnect attempts reached`);
      return;
    }

    this.reconnectAttempts++;
    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);

    console.log(
      `[${this.chainKey}] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`
    );

    await new Promise((resolve) => setTimeout(resolve, delay));

    try {
      await this.stop();
      await this.start();
      this.reconnectAttempts = 0;
    } catch (error) {
      console.error(`[${this.chainKey}] Reconnect failed:`, error);
      // Fix: use setTimeout instead of recursive call to avoid stack overflow
      setTimeout(() => {
        void this.handleReconnect();
      }, 1000);
    }
  }
}

export async function startWebSocketIndexers(): Promise<Map<string, EVMWebSocketIndexer>> {
  const indexers = new Map<string, EVMWebSocketIndexer>();

  const chains = Object.keys(POOL_ADDRESSES).filter((key) => POOL_ADDRESSES[key]);

  for (const chainKey of chains) {
    const indexer = new EVMWebSocketIndexer({
      chainKey,
      poolAddress: POOL_ADDRESSES[chainKey],
      rpcUrl: RPC_ENDPOINTS[chainKey],
    });

    await indexer.start();
    indexers.set(chainKey, indexer);
  }

  return indexers;
}

